import functools
def lead(x):
    @functools.lru_cache(None)
    def d(l, r): return 0 if l > r else max(x[l] - d(l + 1, r), x[r] - d(l, r - 1))
    return d(0, len(x) - 1)
def first(x): return (sum(x) + lead(x)) // 2
def slow(x):
    @functools.lru_cache(None)
    def f(l, r, mine, theirs, turn):
        if l > r: return mine
        a = f(l + 1, r, mine + x[l] * (turn == 0), theirs + x[l] * (turn == 1), 1 - turn)
        b = f(l, r - 1, mine + x[r] * (turn == 0), theirs + x[r] * (turn == 1), 1 - turn)
        if turn == 0: return max(a, b)
        # the second player maximises their own score, which minimises the first player's share of a fixed total
        return min(a, b)
    return f(0, len(x) - 1, 0, 0, 0)
result = slow((4, 5, 1, 3))

